de:\r\n- `@azure/event-hubs` and `@azure/eventhubs-checkpointstore-blob` npm packages\r\n- `EventHubProducerClient` constructor\r\n- `createBatch()` and `EventDataBatch.tryAdd()`\r\n- `sendBatch()` for publishing\r\n- `EventHubConsumerClient` with `BlobCheckpointStore`\r\n- `subscribe()` with `SubscriptionEventHandlers` (processEvents, processError)\r\n- `updateCheckpoint()` in the processEvents handler\r\n- `close()` for cleanup\n\n## Generated Code\n\n### event-hubs-demo.ts\n```\n/**\r\n * Azure Event Hubs TypeScript Demo\r\n * Demonstrates sending and receiving events with batching and checkpoint management\r\n */\r\n\r\nimport { \r\n  EventHubProducerClient, \r\n  EventHubConsumerClient,\r\n  ReceivedEventData,\r\n  Subscription\r\n} from \"@azure/event-hubs\";\r\nimport { ContainerClient } from \"@azure/storage-blob\";\r\nimport { BlobCheckpointStore } from \"@azure/eventhubs-checkpointstore-blob\";\r\n\r\n// Configuration - Replace with your actual values\r\nconst CONNECTION_STRING = process.env.EVENT_HUB_CONNECTION_STRING || \"Endpoint=sb://your-namespace.servicebus.windows.net/;SharedAccessKeyName=your-key-name;SharedAccessKey=your-key\";\r\nconst EVENT_HUB_NAME = process.env.EVENT_HUB_NAME || \"your-event-hub\";\r\nconst STORAGE_CONNECTION_STRING = process.env.STORAGE_CONNECTION_STRING || \"DefaultEndpointsProtocol=https;AccountName=your-storage;AccountKey=your-key;EndpointSuffix=core.windows.net\";\r\nconst CONTAINER_NAME = process.env.CONTAINER_NAME || \"eventhub-checkpoints\";\r\nconst CONSUMER_GROUP = process.env.CONSUMER_GROUP || \"$Default\";\r\n\r\n/**\r\n * Producer: Creates and sends a batch of 10 events with custom properties\r\n */\r\nasync function produceEvents(): Promise\u003cvoid\u003e {\r\n  console.log(\"\\n=== PRODUCING EVENTS ===\");\r\n  \r\n  // 1. Create EventHubProducerClient using connection string\r\n  const producer = new EventHubProducerClient(CONNECTION_STRING, EVENT_HUB_NAME);\r\n  \r\n  try {\r\n    // 2. Create a batch with createBatch()\r\n    const batch = await producer.createBatch();\r\n    console.log(`Created batch with max size: ${batch.maxSizeInBytes} bytes`);\r\n    \r\n    // Add 10 events with custom properties\r\n    for (let i = 1; i \u003c= 10; i++) {\r\n      const eventData = {\r\n        body: {\r\n          message: `Event message ${i}`,\r\n          timestamp: new Date().toISOString(),\r\n          sequenceNumber: i\r\n        },\r\n        properties: {\r\n          eventType: \"demo-event\",\r\n          priority: i % 3 === 0 ? \"high\" : \"normal\",\r\n          source: \"typescript-producer\",\r\n          customId: `event-${i}`\r\n        }\r\n      };\r\n      \r\n      // Try to add event to batch\r\n      const isAdded = batch.tryAdd(eventData);\r\n      \r\n      if (!isAdded) {\r\n        console.warn(`Event ${i} could not fit in the batch`);\r\n        break;\r\n      }\r\n      \r\n      console.log(`Added event ${i} to batch`);\r\n    }\r\n    \r\n    // 3. Send the batch using sendBatch()\r\n    console.log(`\\nSending batch with ${batch.count} events...`);\r\n    await producer.sendBatch(batch);\r\n    console.log(\"✓ Batch sent successfully!\");\r\n    \r\n  } catch (error) {\r\n    console.error(\"Error producing events:\", error);\r\n    throw error;\r\n  } finally {\r\n    // 7. Graceful shutdown with close()\r\n    await producer.close();\r\n    console.log(\"✓ Producer closed\");\r\n  }\r\n}\r\n\r\n/**\r\n * Consumer: Receives events using EventHubConsumerClient with checkpoint management\r\n */\r\nasync function consumeEvents(): Promise\u003cSubscription\u003e {\r\n  console.log(\"\\n=== CONSUMING EVENTS ===\");\r\n  \r\n  // 4. Create BlobCheckpointStore for checkpoint management\r\n  const containerClient = new ContainerClient(\r\n    STORAGE_CONNECTION_STRING,\r\n    CONTAINER_NAME\r\n  );\r\n  \r\n  // Create container if it doesn't exist\r\n  await containerClient.createIfNotExists();\r\n  console.log(`✓ Checkpoint container ready: ${CONTAINER_NAME}`);\r\n  \r\n  const checkpointStore = new BlobCheckpointStore(containerClient);\r\n  \r\n  // Create EventHubConsumerClient with BlobCheckpointStore\r\n  const consumer = new EventHubConsumerClient(\r\n    CONSUMER_GROUP,\r\n    CONNECTION_STRING,\r\n    EVENT_HUB_NAME,\r\n    checkpointStore\r\n  );\r\n  \r\n  // 5. Subscribe to events using subscribe() with handlers\r\n  const subscription = consumer.subscribe({\r\n    // 6. Process events handler - prints bodies and updates checkpoints\r\n    processEvents: async (events: ReceivedEventData[], context) =\u003e {\r\n      if (events.length === 0) {\r\n        console.log(`No events received from partition ${context.partitionId}`);\r\n        return;\r\n      }\r\n      \r\n      console.log(`\\n--- Partition ${context.partitionId}: Received ${events.length} event(s) ---`);\r\n      \r\n      for (const event of events) {\r\n        // Print received event body\r\n        console.log(`\\nEvent received:`);\r\n        console.log(`  Body: ${JSON.stringify(event.body)}`);\r\n        console.log(`  Sequence Number: ${event.sequenceNumber}`);\r\n        console.log(`  Offset: ${event.offset}`);\r\n        console.log(`  Enqueued Time: ${event.enqueuedTimeUtc}`);\r\n        \r\n        // Print custom properties\r\n        if (event.properties) {\r\n          console.log(`  Custom Properties:`);\r\n          for (const [key, value] of Object.entries(event.properties)) {\r\n            console.log(`    ${key}: ${value}`);\r\n          }\r\n        }\r\n      }\r\n      \r\n      // Update checkpoint after processing all events in the batch\r\n      await context.updateCheckpoint(events[events.length - 1]);\r\n      console.log(`✓ Checkpoint updated for partition ${context.partitionId}`);\r\n    },\r\n    \r\n    // Process errors handler\r\n    processError: async (error, context) =\u003e {\r\n      console.error(`\\nError on partition ${context.partitionId}:`, error);\r\n      console.error(`  Error name: ${error.name}`);\r\n      console.error(`  Error message: ${error.message}`);\r\n    }\r\n  });\r\n  \r\n  console.log(\"✓ Subscribed to Event Hub, waiting for events...\");\r\n  console.log(\"  (Press Ctrl+C to stop)\\n\");\r\n  \r\n  return subscription;\r\n}\r\n\r\n/**\r\n * Main execution\r\n */\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  let subscription: Subscription | null = null;\r\n  \r\n  try {\r\n    console.log(\"=================================\");\r\n    console.log(\"Azure Event Hubs TypeScript Demo\");\r\n    console.log(\"=================================\");\r\n    \r\n    // Step 1: Produce events\r\n    await produceEvents();\r\n    \r\n    // Wait a moment for events to be available\r\n    console.log(\"\\nWaiting 3 seconds before consuming...\");\r\n    await new Promise(resolve =\u003e setTimeout(resolve, 3000));\r\n    \r\n    // Step 2: Consume events\r\n    subscription = await consumeEvents();\r\n    \r\n    // Keep the consumer running for 30 seconds to receive events\r\n    console.log(\"Consumer will run for 30 seconds...\");\r\n    await new Promise(resolve =\u003e setTimeout(resolve, 30000));\r\n    \r\n  } catch (error) {\r\n    console.error(\"\\nFatal error:\", error);\r\n    process.exit(1);\r\n  } finally {\r\n    // 7. Graceful shutdown\r\n    if (subscription) {\r\n      console.log(\"\\n\\n=== SHUTTING DOWN ===\");\r\n      await subscription.close();\r\n      console.log(\"✓ Consumer subscription closed\");\r\n    }\r\n    \r\n    console.log(\"✓ Demo completed\");\r\n  }\r\n}\r\n\r\n// Handle process termination gracefully\r\nprocess.on(\"SIGINT\", async () =\u003e {\r\n  console.log(\"\\n\\nReceived SIGINT, shutting down gracefully...\");\r\n  process.exit(0);\r\n});\r\n\r\nprocess.on(\"SIGTERM\", async () =\u003e {\r\n  console.log(\"\\n\\nReceived SIGTERM, shutting down gracefully...\");\r\n  process.exit(0);\r\n});\r\n\r\n// Run the demo\r\nmain().catch((error) =\u003e {\r\n  console.error(\"Unhandled error:\", error);\r\n  process.exit(1);\r\n});\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"azure-event-hubs-demo\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"TypeScript demo for Azure Event Hubs with producer and consumer\",\r\n  \"main\": \"event-hubs-demo.ts\",\r\n  \"scripts\": {\r\n    \"start\": \"ts-node event-hubs-demo.ts\",\r\n    \"build\": \"tsc\",\r\n    \"dev\": \"ts-node-dev event-hubs-demo.ts\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/event-hubs\": \"^5.11.0\",\r\n    \"@azure/eventhubs-checkpointstore-blob\": \"^1.0.1\",\r\n    \"@azure/storage-blob\": \"^12.17.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^20.11.0\",\r\n    \"ts-node\": \"^10.9.2\",\r\n    \"ts-node-dev\": \"^2.0.0\",\r\n    \"typescript\": \"^5.3.3\"\r\n  },\r\n  \"keywords\": [\r\n    \"azure\",\r\n    \"event-hubs\",\r\n    \"typescript\",\r\n    \"messaging\",\r\n    \"streaming\"\r\n  ],\r\n  \"author\": \"\",\r\n  \"license\": \"MIT\"\r\n}\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"moduleResolution\": \"node\",\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true\r\n  },\r\n  \"include\": [\"*.ts\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n### README.md\n```\n# Azure Event Hubs TypeScript Demo\r\n\r\nA comprehensive TypeScript example demonstrating Azure Event Hubs producer and consumer patterns with checkpoint management.\r\n\r\n## Features\r\n\r\n- ✅ **EventHubProducerClient** - Creates producer with connection string\r\n- ✅ **Batch Processing** - Creates batches and adds 10 events with custom properties\r\n- ✅ **Event Sending** - Sends batches using sendBatch()\r\n- ✅ **EventHubConsumerClient** - Configures consumer with BlobCheckpointStore\r\n- ✅ **Event Subscription** - Subscribes with processEvents and processError handlers\r\n- ✅ **Checkpoint Management** - Tracks progress and updates checkpoints\r\n- ✅ **Graceful Shutdown** - Proper cleanup with close()\r\n- ✅ **Async/Await Patterns** - Modern TypeScript async handling\r\n\r\n## Required Packages\r\n\r\n```json\r\n{\r\n  \"@azure/event-hubs\": \"^5.11.0\",\r\n  \"@azure/eventhubs-checkpointstore-blob\": \"^1.0.1\",\r\n  \"@azure/storage-blob\": \"^12.17.0\"\r\n}\r\n```\r\n\r\n## Installation\r\n\r\n```bash\r\nnpm install\r\n```\r\n\r\n## Configuration\r\n\r\nSet the following environment variables before running:\r\n\r\n```bash\r\n# Event Hub connection string\r\nexport EVENT_HUB_CONNECTION_STRING=\"Endpoint=sb://YOUR-NAMESPACE.servicebus.windows.net/;SharedAccessKeyName=YOUR-KEY-NAME;SharedAccessKey=YOUR-KEY\"\r\n\r\n# Event Hub name\r\nexport EVENT_HUB_NAME=\"your-event-hub\"\r\n\r\n# Azure Storage connection string for checkpoints\r\nexport STORAGE_CONNECTION_STRING=\"DefaultEndpointsProtocol=https;AccountName=YOUR-ACCOUNT;AccountKey=YOUR-KEY;EndpointSuffix=core.windows.net\"\r\n\r\n# Container name for checkpoints\r\nexport CONTAINER_NAME=\"eventhub-checkpoints\"\r\n\r\n# Consumer group (optional, defaults to $Default)\r\nexport CONSUMER_GROUP=\"$Default\"\r\n```\r\n\r\n### Windows (PowerShell)\r\n\r\n```powershell\r\n$env:EVENT_HUB_CONNECTION_STRING=\"Endpoint=sb://...\"\r\n$env:EVENT_HUB_NAME=\"your-event-hub\"\r\n$env:STORAGE_CONNECTION_STRING=\"DefaultEndpointsProtocol=https;...\"\r\n$env:CONTAINER_NAME=\"eventhub-checkpoints\"\r\n```\r\n\r\n## Usage\r\n\r\n### Run with ts-node\r\n\r\n```bash\r\nnpm start\r\n```\r\n\r\n### Build and run\r\n\r\n```bash\r\nnpm run build\r\nnode dist/event-hubs-demo.js\r\n```\r\n\r\n### Development mode with auto-reload\r\n\r\n```bash\r\nnpm run dev\r\n```\r\n\r\n## How It Works\r\n\r\n### 1. Producer (Sending Events)\r\n\r\nThe producer:\r\n- Creates an `EventHubProducerClient` with connection string\r\n- Creates a batch using `createBatch()`\r\n- Adds 10 events with custom properties (eventType, priority, source, customId)\r\n- Sends the batch using `sendBatch()`\r\n- Closes the producer gracefully\r\n\r\n### 2. Consumer (Receiving Events)\r\n\r\nThe consumer:\r\n- Creates a `BlobCheckpointStore` for checkpoint persistence\r\n- Creates an `EventHubConsumerClient` with the checkpoint store\r\n- Subscribes to events using `subscribe()` with two handlers:\r\n  - **processEvents**: Receives events, prints bodies, and updates checkpoints\r\n  - **processError**: Handles errors from any partition\r\n- Runs for 30 seconds (configurable) before closing\r\n\r\n### 3. Checkpoint Management\r\n\r\nCheckpoints are automatically:\r\n- Stored in Azure Blob Storage\r\n- Updated after processing each batch of events\r\n- Used to resume from the last processed event on restart\r\n\r\n### 4. Graceful Shutdown\r\n\r\nThe program handles:\r\n- SIGINT (Ctrl+C)\r\n- SIGTERM signals\r\n- Proper cleanup of producers and consumers\r\n- Subscription closure\r\n\r\n## Output Example\r\n\r\n```\r\n=== PRODUCING EVENTS ===\r\nCreated batch with max size: 1048576 bytes\r\nAdded event 1 to batch\r\nAdded event 2 to batch\r\n...\r\n✓ Batch sent successfully!\r\n✓ Producer closed\r\n\r\n=== CONSUMING EVENTS ===\r\n✓ Checkpoint container ready: eventhub-checkpoints\r\n✓ Subscribed to Event Hub, waiting for events...\r\n\r\n--- Partition 0: Received 10 event(s) ---\r\n\r\nEvent received:\r\n  Body: {\"message\":\"Event message 1\",\"timestamp\":\"2026-04-30T...\",\"sequenceNumber\":1}\r\n  Sequence Number: 123\r\n  Offset: 456\r\n  Enqueued Time: 2026-04-30T...\r\n  Custom Properties:\r\n    eventType: demo-event\r\n    priority: normal\r\n    source: typescript-producer\r\n    customId: event-1\r\n...\r\n✓ Checkpoint updated for partition 0\r\n```\r\n\r\n## Error Handling\r\n\r\nThe demo includes comprehensive error handling:\r\n- Try-catch blocks around producer and consumer operations\r\n- Process-level error handlers for unhandled rejections\r\n- Partition-level error handling with `processError` callback\r\n- Graceful degradation on failures\r\n\r\n## Best Practices Demonstrated\r\n\r\n1. **Connection Management** - Proper client creation and disposal\r\n2. **Batching** - Efficient batch creation with size checking\r\n3. **Checkpointing** - Regular checkpoint updates for fault tolerance\r\n4. **Error Handling** - Comprehensive error handling at all levels\r\n5. **Resource Cleanup** - Graceful shutdown with proper cleanup\r\n6. **Async/Await** - Modern async patterns throughout\r\n7. **Type Safety** - Full TypeScript typing for safety\r\n\r\n## Learn More\r\n\r\n- [Azure Event Hubs Documentation](https://docs.microsoft.com/azure/event-hubs/)\r\n- [Azure Event Hubs SDK for JavaScript](https://github.com/Azure/azure-sdk-for-js/tree/main/sdk/eventhub/event-hubs)\r\n- [Event Hubs Checkpoint Store](https://github.com/Azure/azure-sdk-for-js/tree/main/sdk/eventhub/eventhubs-checkpointstore-blob)\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.)\r\n4. **Error Handling** — Are errors handled properly? Retries? Timeouts?\r\n5. **Code Quality** — Clean, readable, well-structured code?\r\n\r\n## Prompt-Specific Criteria\r\n\r\nIn addition to general criteria, evaluate each prompt-specific criterion listed in the \"Prompt-Specific Evaluation Criteria\" section (if provided). Each criterion is either MET (passed) or NOT MET (failed).\r\n\r\n## Scoring\r\n\r\nFor EACH criterion (general + prompt-specific), determine:\r\n- **passed**: true if the criterion is fully met, false otherwise\r\n- **reason**: brief explanation of why it passed or failed\r\n\r\nThe overall score = number of passed criteria out of total criteria.\r\n\r\n## Output Format\r\n\r\nRespond with ONLY a JSON object, no markdown fencing, no explanation:\r\n\r\n```json\r\n{\"scores\":{\"criteria\":[{\"name\":\"criterion name\",\"passed\":true,\"reason\":\"brief explanation\"},{\"name\":\"another criterion\",\"passed\":false,\"reason\":\"why it failed\"}]},\"overall_score\":N,\"max_score\":N,\"summary\":\"...\",\"issues\":[\"...\"],\"strengths\":[\"...\"]}\r\n```\r\n\r\nWhere overall_score = count of passed criteria, max_score = total criteria count.\r\n"
